import{a as e,i as t,r as n,t as r}from"./app-DbTmPHyY.js";var i=JSON.parse(`{"path":"/%E7%AC%AC06%E7%AB%A0%20%E9%A1%B9%E7%9B%AE%E7%AE%A1%E7%90%86%E6%A6%82%E8%AE%BA/6.2%20PMBOK%E7%9F%A5%E8%AF%86%E4%BD%93%E7%B3%BB.html","title":"6.2 PMBOK知识体系","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"第06章 项目管理概论/6.2 PMBOK知识体系.md"}`),a={name:`6.2 PMBOK知识体系.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="_6-2-pmbok知识体系" tabindex="-1"><a class="header-anchor" href="#_6-2-pmbok知识体系"><span>6.2 PMBOK知识体系</span></a></h1><h2 id="定义" tabindex="-1"><a class="header-anchor" href="#定义"><span>定义</span></a></h2><p>PMBOK（Project Management Body of Knowledge）是项目管理知识体系指南，由项目管理协会（PMI）发布，包含项目管理的核心知识领域和最佳实践。</p><h2 id="十大知识领域" tabindex="-1"><a class="header-anchor" href="#十大知识领域"><span>十大知识领域</span></a></h2><h3 id="_1-项目整合管理" tabindex="-1"><a class="header-anchor" href="#_1-项目整合管理"><span>1. 项目整合管理</span></a></h3><ul><li>协调项目所有要素</li><li>确保项目目标实现</li></ul><h3 id="_2-项目范围管理" tabindex="-1"><a class="header-anchor" href="#_2-项目范围管理"><span>2. 项目范围管理</span></a></h3><ul><li>定义和控制项目范围</li><li>防止范围蔓延</li></ul><h3 id="_3-项目进度管理" tabindex="-1"><a class="header-anchor" href="#_3-项目进度管理"><span>3. 项目进度管理</span></a></h3><ul><li>制定和控制项目进度</li><li>确保项目按时完成</li></ul><h3 id="_4-项目成本管理" tabindex="-1"><a class="header-anchor" href="#_4-项目成本管理"><span>4. 项目成本管理</span></a></h3><ul><li>估算和控制项目成本</li><li>确保项目在预算内完成</li></ul><h3 id="_5-项目质量管理" tabindex="-1"><a class="header-anchor" href="#_5-项目质量管理"><span>5. 项目质量管理</span></a></h3><ul><li>确保项目满足质量要求</li><li>实施质量保证和控制</li></ul><h3 id="_6-项目资源管理" tabindex="-1"><a class="header-anchor" href="#_6-项目资源管理"><span>6. 项目资源管理</span></a></h3><ul><li>管理项目资源</li><li>包括人力、物资、设备等</li></ul><h3 id="_7-项目沟通管理" tabindex="-1"><a class="header-anchor" href="#_7-项目沟通管理"><span>7. 项目沟通管理</span></a></h3><ul><li>管理项目沟通</li><li>确保信息及时传递</li></ul><h3 id="_8-项目风险管理" tabindex="-1"><a class="header-anchor" href="#_8-项目风险管理"><span>8. 项目风险管理</span></a></h3><ul><li>识别和管理项目风险</li><li>降低风险影响</li></ul><h3 id="_9-项目采购管理" tabindex="-1"><a class="header-anchor" href="#_9-项目采购管理"><span>9. 项目采购管理</span></a></h3><ul><li>管理项目采购活动</li><li>选择供应商和签订合同</li></ul><h3 id="_10-项目干系人管理" tabindex="-1"><a class="header-anchor" href="#_10-项目干系人管理"><span>10. 项目干系人管理</span></a></h3><ul><li>管理项目干系人</li><li>满足干系人需求</li></ul><h2 id="五大过程组" tabindex="-1"><a class="header-anchor" href="#五大过程组"><span>五大过程组</span></a></h2><h3 id="_1-启动过程组" tabindex="-1"><a class="header-anchor" href="#_1-启动过程组"><span>1. 启动过程组</span></a></h3><ul><li>定义项目或阶段</li><li>获得授权开始项目</li></ul><h3 id="_2-规划过程组" tabindex="-1"><a class="header-anchor" href="#_2-规划过程组"><span>2. 规划过程组</span></a></h3><ul><li>制定项目计划</li><li>明确项目目标和方案</li></ul><h3 id="_3-执行过程组" tabindex="-1"><a class="header-anchor" href="#_3-执行过程组"><span>3. 执行过程组</span></a></h3><ul><li>执行项目计划</li><li>完成项目工作</li></ul><h3 id="_4-监控过程组" tabindex="-1"><a class="header-anchor" href="#_4-监控过程组"><span>4. 监控过程组</span></a></h3><ul><li>监控项目进展</li><li>纠正偏差</li></ul><h3 id="_5-收尾过程组" tabindex="-1"><a class="header-anchor" href="#_5-收尾过程组"><span>5. 收尾过程组</span></a></h3><ul><li>结束项目或阶段</li><li>总结经验教训</li></ul><h2 id="pmbok的价值" tabindex="-1"><a class="header-anchor" href="#pmbok的价值"><span>PMBOK的价值</span></a></h2><h3 id="标准化" tabindex="-1"><a class="header-anchor" href="#标准化"><span>标准化</span></a></h3><ul><li>提供统一的项目管理术语和方法</li><li>便于跨组织沟通</li></ul><h3 id="最佳实践" tabindex="-1"><a class="header-anchor" href="#最佳实践"><span>最佳实践</span></a></h3><ul><li>总结项目管理的成功经验</li><li>提高项目成功率</li></ul><h3 id="职业发展" tabindex="-1"><a class="header-anchor" href="#职业发展"><span>职业发展</span></a></h3><ul><li>作为PMP考试的基础</li><li>提升项目管理专业能力</li></ul><h2 id="关键考点" tabindex="-1"><a class="header-anchor" href="#关键考点"><span>关键考点</span></a></h2><ol><li><strong>PMBOK十大知识领域</strong></li><li><strong>五大过程组</strong></li><li><strong>各知识领域的核心内容</strong></li></ol><h2 id="记忆口诀" tabindex="-1"><a class="header-anchor" href="#记忆口诀"><span>记忆口诀</span></a></h2><p>整范进成本，质资沟风采干，十大领域要记全</p><h2 id="典型例题" tabindex="-1"><a class="header-anchor" href="#典型例题"><span>典型例题</span></a></h2><p><strong>例题</strong>：PMBOK包含多少个知识领域？ A. 5个 B. 8个 C. 10个 D. 12个</p><p><strong>答案</strong>：C</p><p><strong>解析</strong>：PMBOK包含十大知识领域：整合管理、范围管理、进度管理、成本管理、质量管理、资源管理、沟通管理、风险管理、采购管理、干系人管理。</p>`,50)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};